import {session,logout} from './auth.js';
export const emitterContext={emitters:[],active:null};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function scopedUrl(path){const url=new URL(path,location.origin);if(emitterContext.active)url.searchParams.set('emitter',emitterContext.active.id);return url.pathname+url.search;}
export async function initializeEmitters(){
 const response=await fetch('/api/emitters'),result=await response.json();if(!response.ok)throw Error(result.error||'No se pueden cargar los emisores.');emitterContext.emitters=result.emitters;
 const key='adg-emitter-'+session.user.id,requested=new URL(location.href).searchParams.get('emitter');let remembered;try{remembered=sessionStorage.getItem(key);}catch{}
 const selected=emitterContext.emitters.find(e=>e.id===(requested||remembered))||(!requested?emitterContext.emitters.find(e=>e.active)||emitterContext.emitters[0]:null);
 if(!selected){
  document.querySelector('#app').innerHTML=`<main class="auth-page"><section class="auth-card panel"><h1>${requested?'Emisor no disponible':'Sin emisores asignados'}</h1><p>${requested?'Tu cuenta no tiene acceso al emisor de este enlace.':'La cuenta principal puede asignarte acceso a una empresa o autónomo.'}</p>${emitterContext.emitters.length?`<label for="available-emitter">Tus emisores</label><select id="available-emitter">${emitterContext.emitters.map(e=>`<option value="${esc(e.id)}">${esc(e.name)}</option>`).join('')}</select><button class="btn primary" id="open-emitter">Entrar</button>`:''}<button class="btn" id="emitter-logout">Cerrar sesión</button></section></main>`;
  document.querySelector('#emitter-logout').addEventListener('click',logout);document.querySelector('#open-emitter')?.addEventListener('click',()=>{const url=new URL(location.href);url.searchParams.set('emitter',document.querySelector('#available-emitter').value);location.assign(url);});
  await new Promise(()=>{});
 }
 emitterContext.active=selected;try{sessionStorage.setItem(key,selected.id);}catch{}
 // The issuer is captured for this document's lifetime. Other tabs cannot change it.
 const tabEmitter=selected.id,previousFetch=window.fetch.bind(window);
 window.fetch=(input,init={})=>{
  const url=new URL(typeof input==='string'?input:input?.url||String(input),location.href),path=url.pathname;
  if(url.origin===location.origin&&path.startsWith('/api/')&&!path.startsWith('/api/auth/')&&!path.startsWith('/api/users')&&!path.startsWith('/api/emitters')&&path!=='/api/security-audit'){
   const headers=new Headers(input instanceof Request?input.headers:undefined);new Headers(init.headers).forEach((v,k)=>headers.set(k,v));headers.set('X-Emitter-ID',tabEmitter);return previousFetch(input,{...init,headers});
  }
  return previousFetch(input,init);
 };
 return selected;
}
export function createEmitterViews({shell,heading,esc,icon,toast,modal,beforeAction,switchEmitter}){
 async function refresh(){const response=await fetch('/api/emitters'),data=await response.json();if(!response.ok)throw Error(data.error);emitterContext.emitters=data.emitters;}
 async function render(){
  await refresh();
  shell(heading('Empresas y autónomos','Elige quién emite cada factura. Cada perfil conserva sus propios datos y cuentas.',`<button class="btn primary" data-emitter-action="new">${icon('plus')} Nuevo emisor</button>`)+`<section class="emitter-grid">${emitterContext.emitters.map(e=>`<article class="panel emitter-card ${!e.active?'emitter-archived':''}"><div class="emitter-card-heading"><span class="emitter-kind">${e.kind==='professional'?'Autónomo':'Empresa'}</span><span class="badge ${e.active?'':'draft'}">${e.active?'Activo':'Archivado'}</span></div><h2>${esc(e.name)}</h2><p>NIF ${esc(e.nif||'Pendiente')}</p>${e.isOriginal?'<small>Perfil original · histórico conservado</small>':''}<div class="actions"><button class="btn primary" data-emitter-open="${esc(e.id)}">${e.id===emitterContext.active.id?'Perfil actual':'Abrir perfil'}</button><button class="btn ghost" data-emitter-archive="${esc(e.id)}">${e.active?'Archivar':'Reactivar'}</button></div></article>`).join('')}</section><section class="panel formpanel"><h2>Accesos del equipo</h2><p>En Usuarios puedes asignar a cada persona los emisores a los que entra y su rol en cada uno. Un usuario normal consulta sus propias facturas dentro de esos perfiles.</p><button class="btn" data-nav="users">Gestionar usuarios</button></section>`,'Emisores');
 }
 function createModal(){modal.className='';modal.innerHTML=`<button class="iconbtn close" data-action="close-modal" aria-label="Cerrar">${icon('close')}</button><h2>Nuevo emisor</h2><p>Los documentos se emitirán a nombre de esta empresa o autónomo.</p><form id="emitter-form"><div class="fields"><div class="field full"><label for="emitter-kind">Tipo de emisor</label><select id="emitter-kind" name="kind"><option value="company">Empresa</option><option value="professional">Autónomo</option></select></div><div class="field full"><label for="emitter-name">Nombre o razón social</label><input id="emitter-name" name="name" maxlength="100" required></div><div class="field"><label for="emitter-nif">NIF</label><input id="emitter-nif" name="nif" maxlength="25" required></div><div class="field"><label for="emitter-email">Correo electrónico</label><input id="emitter-email" name="email" type="email"></div><div class="field full"><label for="emitter-address">Dirección fiscal</label><textarea id="emitter-address" name="address" maxlength="300" required></textarea></div><div class="field full"><label for="emitter-iban">Cuenta bancaria</label><input id="emitter-iban" name="iban" maxlength="40"></div></div><div class="form-error" role="alert"></div><div class="actions"><button class="btn" type="button" data-action="close-modal">Cancelar</button><button class="btn primary" type="submit">Crear emisor</button></div></form>`;modal.showModal();modal.querySelector('#emitter-name').focus();}
 document.addEventListener('click',async event=>{const button=event.target.closest('button');if(!button)return;try{
  if(button.dataset.emitterOpen){await switchEmitter(button.dataset.emitterOpen);return;}
  if(button.dataset.emitterAction==='new'){await beforeAction();createModal();return;}
  if(button.dataset.emitterArchive){await beforeAction();const e=emitterContext.emitters.find(e=>e.id===button.dataset.emitterArchive);modal.className='';modal.innerHTML=`<h2>${e.active?'Archivar':'Reactivar'} emisor</h2><p>${esc(e.name)} · ${esc(e.nif)}</p><p>${e.active?'Se conservarán sus facturas, cobros, plantillas y accesos. La cuenta principal podrá consultar el histórico y reactivarlo.':'Los usuarios asignados volverán a poder trabajar con este perfil.'}</p><div class="form-error" role="alert"></div><div class="actions"><button class="btn" data-action="close-modal">Cancelar</button><button class="btn primary" data-emitter-confirm="${esc(e.id)}">${e.active?'Archivar emisor':'Reactivar emisor'}</button></div>`;modal.showModal();return;}
  if(button.dataset.emitterConfirm){const e=emitterContext.emitters.find(e=>e.id===button.dataset.emitterConfirm);button.disabled=true;const response=await fetch('/api/emitters/'+encodeURIComponent(e.id),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({active:!e.active})}),data=await response.json();if(!response.ok)throw Error(data.error);modal.close();if(e.id===emitterContext.active.id){location.reload();return;}await render();toast(data.emitter.active?'Emisor reactivado':'Emisor archivado');}
 }catch(error){const field=modal.open&&modal.querySelector('.form-error');if(field)field.textContent=error.message;else toast(error.message);button.disabled=false;}});
 document.addEventListener('submit',async event=>{if(event.target.id!=='emitter-form')return;event.preventDefault();const form=event.target,button=form.querySelector('[type=submit]');button.disabled=true;try{const response=await fetch('/api/emitters',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(form)))}),data=await response.json();if(!response.ok)throw Error(data.error);modal.close();await refresh();await switchEmitter(data.emitter.id);}catch(error){form.querySelector('.form-error').textContent=error.message;button.disabled=false;}});
 return {render};
}
